import{_ as t,o,c as a,ah as r}from"./chunks/framework.CW0Xh8qL.js";const n="/projects/4-Ch-Knob-Line-Follower/en/gpio-version/assets/image1.CLTQSzgz.png",i="/projects/4-Ch-Knob-Line-Follower/en/gpio-version/assets/image2.bilc1Yz9.png",s="/projects/4-Ch-Knob-Line-Follower/en/gpio-version/assets/image3.BKekvn4i.png",l="/projects/4-Ch-Knob-Line-Follower/en/gpio-version/assets/image4.yfBfWl4d.png",d="/projects/4-Ch-Knob-Line-Follower/en/gpio-version/assets/image7.CglEQ-Lp.png",h="/projects/4-Ch-Knob-Line-Follower/en/gpio-version/assets/image8.TuZYTICK.png",c="/projects/4-Ch-Knob-Line-Follower/en/gpio-version/assets/image9.v4JfId3u.png",f=JSON.parse('{"title":"2. Arduino Example","description":"","frontmatter":{},"headers":[],"relativePath":"docs/2_Arduino_Example.md","filePath":"docs/2_Arduino_Example.md"}'),p={name:"docs/2_Arduino_Example.md"};function g(m,e,u,b,_,x){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="_2-arduino-example" tabindex="-1">2. Arduino Example <a class="header-anchor" href="#_2-arduino-example" aria-label="Permalink to &quot;2. Arduino Example&quot;">​</a></h1><h2 id="_2-1-preparation" tabindex="-1">2.1 Preparation <a class="header-anchor" href="#_2-1-preparation" aria-label="Permalink to &quot;2.1 Preparation&quot;">​</a></h2><p>An Arduino UNO and an expansion board are used in this example. Connect the 4-ch line follower sensor to the 5V pin, GND pin, and four IO pins on the expansion board with a 6P cable.</p><img loading="lazy" height="865" width="822" src="'+n+'" class="common_img" style="width:400px;"><table tabindex="0"><thead><tr><th style="text-align:center;">Pin</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">5V</td><td style="text-align:center;">Power input</td></tr><tr><td style="text-align:center;">GND</td><td style="text-align:center;">Power ground</td></tr><tr><td style="text-align:center;">S1</td><td style="text-align:center;">D4</td></tr><tr><td style="text-align:center;">S2</td><td style="text-align:center;">D5</td></tr><tr><td style="text-align:center;">S3</td><td style="text-align:center;">D3</td></tr><tr><td style="text-align:center;">S4</td><td style="text-align:center;">D2</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The detection distance can be adjusted with the knobs, allowing the sensitivity to be tuned for different environments. For calibration, first place the infrared probes over a black area and adjust the knobs until all blue indicator lights turn on. Then slowly rotate the knobs until the lights just turn off. Next, place the probes over a white area and continue adjusting until the lights just turn on. The probes are now set to the optimal sensitivity, as shown in the figure.</strong></p></div><img loading="lazy" height="204" width="205" src="'+i+'" class="common_img" style="width:300px;"><h2 id="_2-2-example-program" tabindex="-1">2.2 Example Program <a class="header-anchor" href="#_2-2-example-program" aria-label="Permalink to &quot;2.2 Example Program&quot;">​</a></h2><p>The 4-ch line follower sensor works by infrared detection. It has four probes, and each probe includes one transmitter and one receiver.</p><ol><li><p>Connect the Arduino UNO with the expansion board installed to the computer with a USB cable.</p></li><li><p>Open the Arduino example sketch in the <a href="https://drive.google.com/drive/folders/1wAH4bbi8OJHzqooWtr-qJ8P4QdlaKFJ4?usp=sharing" target="_blank" rel="noreferrer">01 Arduino</a> folder.</p></li><li><p>Select the correct board and port. This example is demonstrated with an Arduino UNO on Port 11. Select the port that matches the connected board.</p></li></ol><img loading="lazy" height="599" width="1077" src="'+s+'" class="common_img" style="width:500px;"><h2 id="_2-3-program-outcome" tabindex="-1">2.3 Program Outcome <a class="header-anchor" href="#_2-3-program-outcome" aria-label="Permalink to &quot;2.3 Program Outcome&quot;">​</a></h2><ol><li><p>Suitable platforms include Mecanum-wheel, differential-drive, tank, and Ackermann chassis.</p></li><li><p>Prepare a sheet of white paper with a black line, or draw several black lines on white paper.</p></li><li><p>Place the sensor probes over the black line and the white background, then open the <strong>Serial Monitor</strong> in the Arduino IDE. The readings from the four probes are displayed as <code>1</code> or <code>0</code>. When a probe is over a black line, the corresponding indicator turns off, and the reading is <code>0</code>. When a probe is over a white area, the corresponding indicator turns on, and the reading is <code>1</code>.</p></li></ol><img loading="lazy" height="276" width="639" src="'+l+'" class="common_img" style="width:400px;"><h2 id="_2-4-program-analysis" tabindex="-1">2.4 Program Analysis <a class="header-anchor" href="#_2-4-program-analysis" aria-label="Permalink to &quot;2.4 Program Analysis&quot;">​</a></h2><p>The program uses four line following channels to detect the black line and outputs the logic levels of each channel through the serial port. A reading of <code>0</code> indicates that the corresponding probe is over a black line. A reading of <code>1</code> indicates that the corresponding probe is over a white area. The program is shown in the figure below.</p><img loading="lazy" height="120" width="861" src="'+d+'" class="common_img" style="width:700px;"><img loading="lazy" height="700" width="953" src="'+h+'" class="common_img" style="width:700px;"><img loading="lazy" height="435" width="932" src="'+c+'" class="common_img" style="width:700px;">',19)])])}const y=t(p,[["render",g]]);export{f as __pageData,y as default};
